 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    lines = {}

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two-cell eastward bar, ending in a 1 one row above.
                for k in (1, 2):
                    put(r, c + k, 5)
                put(r - 1, c + 2, 1)
            elif color in (2, 3, 6):
                if color == 2:
                    dr, dc, length = 0, -1, 4
                elif color == 3:
                    dr, dc, length = 1, 0, 3
                else:
                    dr, dc, length = -1, 0, 6
                path = []
                for k in range(1, length):
                    rr, cc = r + dr * k, c + dc * k
                    put(rr, cc, 5)
                    path.append((rr, cc))
                rr, cc = r + dr * length, c + dc * length
                put(rr, cc, color)
                lines.setdefault(color, []).append([(r, c)] + path + [(rr, cc)])

    # Where a horizontal 2-line crosses a vertical 3/6-line, place a 4;
    # each 4 emits its characteristic southwest diagonal ray.
    centers = set()
    for horizontal in lines.get(2, []):
        for vertical_color in (3, 6):
            for vertical in lines.get(vertical_color, []):
                hs = set(horizontal)
                for rr, cc in vertical:
                    if (rr, cc) in hs:
                        centers.add((rr, cc))
    for r, c in centers:
        put(r, c, 4)
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == 0:
                out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out

